<?php
declare(strict_types=1);
if (session_status() !== PHP_SESSION_ACTIVE) { session_start(); }
require_once __DIR__ . '/config.php';
if (empty($_SESSION['user'])) { header('Location: login.php'); exit; }
$u=$_SESSION['user'];$settings=[];try{foreach(db()->query('SELECT setting_key,setting_value FROM madapt_settings')->fetchAll(PDO::FETCH_ASSOC) as $r)$settings[$r['setting_key']]=$r['setting_value'];}catch(Throwable $e){}
$company=$settings['company_name']??'MADAPT ULDs';$logo=$settings['logo_path']??'';$role=strtoupper((string)($u['role']??'OPERATOR'));$isAdmin=$role==='ADMIN';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OPERACIONES — <?=htmlspecialchars($company)?></title><link rel="stylesheet" href="assets/app.css"><style>:root{--primary:<?=htmlspecialchars($settings['primary']??'#087a46')?>}.op-shell{min-height:100vh;background:var(--bg,#f6f9f7)}.op-wrap{max-width:1500px;margin:auto;padding:22px}.op-top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:16px}.op-brand{display:flex;align-items:center;gap:12px}.op-brand img{max-height:48px;max-width:150px;object-fit:contain}.op-title h1{margin:0;color:var(--primary)}.op-title p{margin:4px 0;color:var(--muted,#63756e)}.op-nav{display:flex;gap:8px}.op-nav a,.op-btn{border:1px solid #d4e1dc;background:#fff;color:var(--text,#21322c);padding:9px 12px;border-radius:8px;font-weight:700;text-decoration:none;cursor:pointer}.op-dashboard{display:grid;grid-template-columns:1fr 220px;gap:16px}.op-clock{background:#eef6f2;border:1px solid #d6e6df;border-radius:12px;padding:16px;text-align:center}.op-clock small,.op-clock span{display:block;color:var(--muted,#63756e);font-size:11px}.op-clock strong{display:block;color:var(--primary);font-size:28px;margin:4px 0}.op-controls{display:grid;grid-template-columns:1fr auto 240px;gap:16px;align-items:end;margin-bottom:16px}.op-controls label{display:block;color:var(--muted,#63756e);font-size:12px;margin-bottom:5px}.op-controls input{width:100%;box-sizing:border-box}.op-actions{display:flex;gap:8px}.op-group{margin-bottom:16px}.op-table{width:100%;border-collapse:collapse}.op-table th,.op-table td{padding:9px 8px;border-bottom:1px solid #e1e9e5;text-align:left;vertical-align:middle}.op-table th{font-size:12px;color:#5d7169}.op-status{display:inline-block;padding:4px 8px;border-radius:999px;background:#edf1ef;color:#63756e;font-size:11px;font-weight:800}.op-status.live{background:#fff2cf;color:#8a6200}.op-status.done{background:#dff4e8;color:#137343}.op-start,.op-complete{border:0;border-radius:7px;padding:7px 9px;font-weight:800;cursor:pointer;margin:2px}.op-start{background:#eef6ff;color:#1769aa}.op-complete{background:#e3f5e9;color:#137343}.op-start:disabled,.op-complete:disabled{opacity:.45;cursor:not-allowed}.op-table tr.live-row{background:rgba(255,193,7,.06)}.op-table tr.done-row{opacity:.82}.op-footer{margin-top:24px;padding:15px 0;border-top:1px solid #dfe9e5;text-align:center;color:#63756e;font-size:12px}@media(max-width:850px){.op-top,.op-controls{display:block}.op-nav{margin-top:10px}.op-dashboard{display:block}.op-clock{margin-top:12px}.op-actions{margin-top:12px}.op-table{font-size:12px}.op-table th:nth-child(6),.op-table td:nth-child(6){display:none}.op-wrap{padding:12px}}</style></head><body><div class="op-shell"><div class="op-wrap"><div class="op-top"><div class="op-brand"><?php if($logo):?><img src="<?=htmlspecialchars($logo)?>" alt="Logo"><?php endif;?><div class="op-title"><h1>OPERACIONES</h1><p>B787-900 Ground Turnaround · 70 minutes</p></div></div><div class="op-nav"><a href="index.php">← MADAPT ULDs</a><?php if($isAdmin):?><button class="op-btn" id="resetBtn">Reset Operations</button><?php endif;?></div></div><div id="app"><div class="box"><b>Loading...</b></div></div><div class="op-footer">MADAPT ULDs Professional · Ethiopian Airlines</div></div></div><script>const IS_ADMIN=<?=json_encode($isAdmin)?>,CURRENT_USER=<?=json_encode($u,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let state=null,timer=null;const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const fmt=ms=>{const n=Math.max(0,Math.floor(Number(ms||0)/1000)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')};async function call(a,d={}){const r=await fetch('operations.php?action='+encodeURIComponent(a),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d),cache:'no-store'});let j;try{j=await r.json()}catch(e){throw Error('Invalid server response (HTTP '+r.status+')')}if(!j.ok)throw Error(j.error||'Request failed');return j}function render(){const app=document.getElementById('app'),block=state.blockIn?Number(state.blockIn):null,groups={};(state.operations||[]).forEach(x=>(groups[x.op_group]??=[]).push(x));app.innerHTML=`<div class="op-dashboard"><div><div class="box op-controls"><div><label>Block-In</label><div>${block?new Date(block).toLocaleString():'Not set'}</div></div><div class="op-actions"><button class="op-btn" id="blockBtn">${block?'Reset / Set Block-In':'Set Block-In Now'}</button></div><div><label>Operator</label><input id="operator" value="${esc(CURRENT_USER.full_name||CURRENT_USER.username||'')}" placeholder="Operator name"></div></div>${Object.entries(groups).map(([g,rows])=>`<div class="box op-group"><h2>${esc(g)}</h2><div class="table-wrap"><table class="op-table"><thead><tr><th>#</th><th>Operation</th><th>Planned</th><th>Allocated</th><th>Status</th><th>Operator</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr class="${x.status==='Started'?'live-row':x.status==='Completed'?'done-row':''}"><td><b>${x.operation_no}</b></td><td>${esc(x.operation_name)}</td><td>${esc(x.planned_start)}${x.planned_end?' – '+esc(x.planned_end):''}</td><td>${esc(x.allocated||'—')}</td><td><span class="op-status ${x.status==='Started'?'live':x.status==='Completed'?'done':''}">${esc(x.status||'Pending')}</span></td><td>${esc(x.operator_name||'—')}</td><td><button class="op-start" data-a="Started" data-id="${x.id}" ${x.status==='Started'||x.status==='Completed'?'disabled':''}>START</button><button class="op-complete" data-a="Completed" data-id="${x.id}" ${x.status==='Completed'?'disabled':''}>COMPLETE</button></td></tr>`).join('')}</tbody></table></div></div>`).join('')}</div><div class="op-clock"><small>TURNAROUND ELAPSED</small><strong id="elapsed">${fmt(block?Date.now()-block:0)}</strong><span>Target · 01:10:00</span></div></div>`;document.getElementById('blockBtn').onclick=async()=>{try{state=await call('block_in',{iso:new Date().toISOString()});render()}catch(e){alert(e.message)}};app.querySelectorAll('[data-a]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;state=await call('update',{id:+b.dataset.id,action:b.dataset.a,operator:document.getElementById('operator')?.value||''});render()}catch(e){b.disabled=false;alert(e.message)}});if(timer)clearInterval(timer);timer=setInterval(()=>{const e=document.getElementById('elapsed');if(e&&block)e.textContent=fmt(Date.now()-block)},1000)}async function init(){try{state=await call('data');render()}catch(e){document.getElementById('app').innerHTML='<div class="box error"><b>Could not load operations</b><p>'+esc(e.message)+'</p></div>'}}document.getElementById('resetBtn')?.addEventListener('click',async()=>{if(!confirm('Reset all operation statuses and Block-In?'))return;try{state=await call('reset');render()}catch(e){alert(e.message)}});init();</script></body></html>
